(out/'impact-dispositions.json').write_text(json.dumps(dict(run=w['run'],group=2,dispositions=disps),indent=2,ensure_ascii=False)+'\n')
(out/'interface-evidence.json').write_text(json.dumps(dict(run=w['run'],group=2,reviewer=reviewer,scope='Changed-supplier interfaces only; no new broad independent proof audit.',raw_hash_checks=workhash,exports={s:dict(sha256=sha(s),clause=export(s)) for s in sorted(allids)},consumer_adjudications=reasons),indent=2,ensure_ascii=False)+'\n')
(out/'defect-proposals.json').write_text('[]\n');(out/'carrier-deltas.json').write_text('[]\n')
